// Form Pair — R,U-only algorithms that form the BR pair (DBR corner + BR
// edge) as a joinable 2x2x3-intact unit, WITHOUT inserting it or fixing EO.
//
// Generated by scripts/generate_form_pair.ts — do not hand-edit; re-run the
// script instead. See that script's header for the derivation:
//
//   - R and U never touch block223 (corners 5,6; edges 5,6,7,9,10) and never
//     flip edge orientation (see cube-state.ts's QUARTER_TURN table — only
//     F/B/S/f/b/x/z have nonzero `eo`), so an <R,U>-only forming step leaves
//     both block223 and EO completely untouched.
//   - "Formed" is purely geometric: DBR corner 7 + BR edge 11's own
//     location/orientation matches one of the 15 positions eo-pair's
//     or/ou/mr/mu subsets recognize (ignoring the *other* edges' EO, which
//     is irrelevant to whether the pair itself is mechanically joined).
//   - Each case's `baseState` anchors to the eo-pair (or solved-cube) state
//     its primary alg actually lands on — recognition is still fully
//     alg-derived (`baseState · invert(algs[0])`, see `AlgCaseInput.baseState`),
//     never hand-written, exactly like every other algset here.
//   - A case with more than one variant has *tied* shortest paths to
//     DIFFERENT eo-pair subsets (e.g. an "or" pair equidistant from a
//     "mu" pair) — kept as interchangeable variants so the runner's
//     existing phase-chaining can race them against the live EO pattern's
//     eoPairInsert cost, same as any other multi-variant case.
//   - The 15 states already at a formed position need no case at all:
//     `runPhase`'s built-in zero-move "skip" path (identity pre-AUF already
//     meeting the goal) covers them.
//
// See /DESIGN.md for the algset schema.

import { type AlgSet, defineAlgSet } from "../define.ts";
import { eoPair as eoPairSet } from "../eo-pair/index.ts";
import { type CubeState, solvedCube } from "@moishy/cubing-core";

// Anchor states: the eo-pair case each variant's primary alg lands on, keyed
// by the anchor's own (DBR,BR) position signature. Rebuilt from eo-pair rather
// than hand-stored, so the derivation chain stays fully alg-based.
const ANCHOR_CASE: Record<string, string> = {
  "3.0/8.0": "or-1",
  "0.0/8.0": "or-2",
  "2.0/8.0": "or-19",
  "1.0/8.0": "or-21",
  "2.1/3.0": "ou-1",
  "3.1/0.0": "ou-2",
  "0.1/1.0": "ou-6",
  "1.1/2.0": "ou-9",
  "3.2/3.1": "mu-1",
  "1.2/1.1": "mu-2",
  "0.2/0.1": "mu-6",
  "2.2/2.1": "mu-7",
  "3.0/11.1": "mr-1",
  "2.0/11.1": "mr-3",
  "0.0/11.1": "mr-9",
};

function anchorState(sig: string): CubeState {
  const caseId = ANCHOR_CASE[sig];
  return caseId ? eoPairSet.recognitionState(caseId) : solvedCube();
}

